                    <button onClick={() => setView('new')} style={{ padding: '10px 24px', borderRadius: 10, border: 'none', background: '#6366f1', color: '#fff', fontWeight: 700, fontSize: 14, cursor: 'pointer' }}>
                      Ingresar primer equipo
                    </button>
