      {/* Actions */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {order.estado === 'pendiente' && (
          <>
            <button onClick={() => onCambiarEstado(order, 'confirmado', true)} disabled={advancing}
