            <button onClick={() => onCambiarEstado(order, 'cancelado')} disabled={advancing}
              style={{ padding: '12px', borderRadius: 12, border: '1px solid #fecaca', background: '#fff', color: '#dc2626', fontWeight: 600, fontSize: 13, cursor: 'pointer' }}>
